package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/admission") public class AdmissionController{private final AdmissionService s;public AdmissionController(AdmissionService s){this.s=s;}@PostMapping public ResponseEntity<AdmissionDTO> create(@Valid @RequestBody AdmissionDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<AdmissionDTO> all(){return s.all();}@GetMapping("/{id}") public AdmissionDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public AdmissionDTO update(@PathVariable Long id,@Valid @RequestBody AdmissionDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@PutMapping("/{id}/discharge") public AdmissionDTO discharge(@PathVariable Long id){return s.discharge(id);}@GetMapping("/floor/{floor}") public List<AdmissionDTO> floor(@PathVariable Integer floor){return s.floor(floor);}}
